'use strict';

// MODULES //

var tape = require( 'tape' );
var isDataSet = require( '@stdlib/plot/vega/base/assert/is-dataset' );
var arrays2tidy = require( './../lib' );


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof arrays2tidy, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function returns a data set', function test( t ) {
	var out = arrays2tidy( [ [ 1, 2, 3 ], [ 4, 5, 6 ] ], 'data', [ 'x', 'y' ] );
	t.strictEqual( isDataSet( out ), true, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having a specified name', function test( t ) {
	var out = arrays2tidy( [ [ 1, 2, 3 ], [ 4, 5, 6 ] ], 'beep', [ 'x', 'y' ] );
	t.strictEqual( out.name, 'beep', 'returns expected value' );
	t.end();
});

tape( 'the function converts a list of arrays to a "tidy" data set', function test( t ) {
	var expected;
	var actual;
	var i;

	actual = arrays2tidy( [ [ 1, 2, 3 ], [ 4, 5, 6 ] ], 'data', [ 'x', 'y' ] ).toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'x': 1,
			'y': 4
		},
		{
			'x': 2,
			'y': 5
		},
		{
			'x': 3,
			'y': 6
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function supports specifying field names', function test( t ) {
	var expected;
	var actual;
	var i;

	actual = arrays2tidy( [ [ 1, 2 ], [ 3, 4 ] ], 'data', [ 'a', 'b' ] ).toJSON().values;
	for ( i = 0; i < actual.length; i++ ) {
		actual[ i ] = actual[ i ].toJSON();
	}
	expected = [
		{
			'a': 1,
			'b': 3
		},
		{
			'a': 2,
			'b': 4
		}
	];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});

tape( 'the function returns a data set having no values if provided empty arrays', function test( t ) {
	var expected;
	var actual;

	actual = arrays2tidy( [ [], [] ], 'data', [ 'x', 'y' ] ).toJSON().values;
	expected = [];
	t.deepEqual( actual, expected, 'returns expected value' );
	t.end();
});
